package main

import (
	"errors"
	"testing"
	"time"
)

func TestExpiryRegressionTable(t *testing.T) {
	cases := []struct {
		name       string
		ttl        time.Duration
		createAt   time.Time
		readAt     time.Time
		wantErr    error
		wantDropped bool
	}{
		{name: "fresh readable", ttl: time.Minute, createAt: time.Unix(1000, 0), readAt: time.Unix(1005, 0), wantErr: nil},
		{name: "exactly ttl still live", ttl: time.Minute, createAt: time.Unix(1000, 0), readAt: time.Unix(1060, 0), wantErr: nil},
		{name: "one second past ttl", ttl: time.Minute, createAt: time.Unix(1000, 0), readAt: time.Unix(1061, 0), wantErr: ErrNotFound},
		{name: "well past ttl", ttl: time.Minute, createAt: time.Unix(1000, 0), readAt: time.Unix(2000, 0), wantErr: ErrNotFound},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			store := NewStore(tc.ttl)
			store.now = func() time.Time { return tc.createAt }
			store.Create("s1", "alice")
			before := store.Len()
			store.now = func() time.Time { return tc.readAt }
			_, err := store.Get("s1")
			if tc.wantErr == nil {
				if err != nil {
					t.Fatalf("read: %v", err)
				}
			} else if !errors.Is(err, tc.wantErr) {
				t.Fatalf("read err = %v, want %v", err, tc.wantErr)
			}
			if tc.wantErr != nil && tc.wantDropped != false {
				t.Fatal("mispecified case")
			}
			_ = before
		})
	}
}

